"""Create separate disclosure-scrubbed JFR delivery files after timing has ended.

Never run during a benchmark quiet period. Original recordings remain untouched.
The JDK scrubber removes four disclosure event types. An independent Java audit
compares every retained logical event payload and count, and searches sanitized
bytes for detected sensitive values without emitting those values or their hashes.
No dependencies beyond Python and the already installed JDK are required.
"""

from __future__ import annotations

import argparse
import ctypes
import errno
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys
import tempfile
import time
from zipfile import ZipFile

ROOT = Path(__file__).resolve().parents[2]
HERE = Path(__file__).resolve().parent
REMOVED = (
    "jdk.InitialEnvironmentVariable",
    "jdk.InitialSystemProperty",
    "jdk.SystemProcess",
    "jdk.InitialSecurityProperty",
)
DEFAULT_JDK = Path("/workspace/scratch/d0a0e51b9386/toolchain/jdk-25.0.5+8")


def require(condition: bool, message: str) -> None:
    if not condition:
        raise ValueError(message)


def sha(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def write_new(path: Path, value: object) -> None:
    with path.open("x", encoding="utf-8") as stream:
        json.dump(value, stream, indent=2, sort_keys=True)
        stream.write("\n")


def publish_no_replace(source: Path, destination: Path) -> None:
    require(sys.platform.startswith("linux"), "Atomic publication requires Linux renameat2")
    libc = ctypes.CDLL(None, use_errno=True)
    rename = getattr(libc, "renameat2", None)
    require(rename is not None, "Atomic no-replace publication is unavailable")
    rename.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_int, ctypes.c_char_p, ctypes.c_uint]
    rename.restype = ctypes.c_int
    if rename(-100, os.fsencode(source), -100, os.fsencode(destination), 1):
        error = ctypes.get_errno()
        if error in (errno.EEXIST, errno.ENOTEMPTY):
            raise FileExistsError("Refusing to replace an existing delivery")
        raise OSError(error, "Atomic publication failed")


def run(command: list[str], log: Path, environment: dict[str, str]) -> None:
    with log.open("xb") as stream:
        result = subprocess.run(command, cwd=ROOT, env=environment, stdout=stream,
                                stderr=subprocess.STDOUT, check=False)
    require(result.returncode == 0, "An auxiliary JDK operation failed; private work is preserved")


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--jdk", type=Path, default=DEFAULT_JDK)
    parser.add_argument("--output", type=Path, default=HERE / "delivery-profiles")
    parser.add_argument("--execute-after-timing", action="store_true",
                        help="Explicitly assert that the parent has released the timing quiet period")
    args = parser.parse_args()
    require(args.execute_after_timing, "Do not execute until the timing quiet period has been released")
    jdk = args.jdk.resolve(strict=True)
    output = args.output.parent.resolve(strict=True) / args.output.name
    require(output.is_relative_to(ROOT) and not os.path.lexists(output),
            "Delivery needs a new directory inside this evidence checkout")
    java, jfr = jdk / "bin/java", jdk / "bin/jfr"
    require(java.is_file() and jfr.is_file(), "The requested JDK tools are unavailable")
    summary_path = HERE / "profile-summary.json"
    profile_summary = json.loads(summary_path.read_text())
    auditor = HERE / "JfrDisclosureAudit.java"
    require(auditor.is_file(), "Disclosure auditor source is missing")
    environment = os.environ.copy()
    removed_jvm_overrides = []
    for name in ("JAVA_TOOL_OPTIONS", "JDK_JAVA_OPTIONS", "_JAVA_OPTIONS"):
        if environment.pop(name, None) is not None:
            removed_jvm_overrides.append(name)
    # This work directory is deliberately outside every source/evidence root.
    work = Path(tempfile.mkdtemp(prefix="materializer-jfr-audit-", dir=ROOT.parent))
    require(work.stat().st_dev == output.parent.stat().st_dev, "Publication must remain on one filesystem")
    staging = work / "delivery-profiles"
    staging.mkdir()
    write_new(work / "preparation.json", {
        "format": 1, "createdEpochNs": time.time_ns(), "privateWorkDirectory": str(work),
        "intendedOutput": str(output), "removedJvmOverrideNames": removed_jvm_overrides,
        "originalRecordingsWillBeModified": False,
    })
    source_entries = {}
    with ZipFile(jdk / "lib/src.zip") as archive:
        for name in ("jdk.jfr/jdk/jfr/internal/tool/Scrub.java",
                     "jdk.jfr/jdk/jfr/internal/consumer/filter/ChunkWriter.java"):
            data = archive.read(name)
            source_entries[name] = {"bytes": len(data), "sha256": hashlib.sha256(data).hexdigest()}
    records = []
    try:
        for mode in ("off", "dense"):
            original_record = profile_summary["profileFiles"][mode]
            expected_relative = HERE.relative_to(ROOT).as_posix() + "/frozen-" + mode + "/profile.jfr"
            require(original_record["path"] == expected_relative, "Unexpected original recording path")
            original = ROOT / original_record["path"]
            require(original.is_file() and original.stat().st_size == original_record["bytes"]
                    and sha(original) == original_record["sha256"], "Original JFR identity changed")
            expected_counts = json.loads((HERE / ("frozen-" + mode) / "event-counts.json").read_text())
            folder = staging / ("frozen-" + mode)
            folder.mkdir()
            sanitized = folder / "profile.jfr"
            require(not os.path.lexists(sanitized), "Scrub output must be new; the JDK tool can overwrite files")
            scrub = [str(jfr), "scrub", "--exclude-events", ",".join(REMOVED), str(original), str(sanitized)]
            audit_path = folder / "redacted-audit.json"
            audit_command = [str(java), "-Xms64m", "-Xmx512m", str(auditor),
                             str(original), str(sanitized), str(audit_path)]
            write_new(folder / "commands.json", {"scrubArgv": scrub, "auditArgv": audit_command,
                                                 "cwd": str(ROOT), "recordedDestinationWasFresh": True})
            run(scrub, work / (mode + "-scrub.log"), environment)
            run(audit_command, work / (mode + "-audit.log"), environment)
            audit = json.loads(audit_path.read_text())
            require(audit["status"] == "passed" and audit["retainedEventsEquivalent"]
                    and audit["detectedSecretByteSearchPassed"] and audit["excludedDisclosureEventsAbsent"],
                    "Disclosure or retained-event verification did not pass")
            require(audit["originalEventCounts"] == expected_counts,
                    "Audited original event counts differ from the preserved diagnostic extraction")
            removed_counts = {name: expected_counts.get(name, 0) for name in REMOVED}
            require(audit["removedEventCounts"] == removed_counts and all(removed_counts.values()),
                    "Removed-event set/counts differ from the intended disclosure records")
            require(original.stat().st_size == original_record["bytes"] and sha(original) == original_record["sha256"],
                    "Original recording changed during sanitization")
            sanitized_record = {"path": (output / ("frozen-" + mode) / "profile.jfr").relative_to(ROOT).as_posix(),
                                "bytes": sanitized.stat().st_size, "sha256": sha(sanitized)}
            record = {
                "mode": mode, "original": original_record, "sanitized": sanitized_record,
                "removedEventCounts": removed_counts, "retainedEventsEquivalent": True,
                "retainedPayloadDigestAlgorithm": audit["retainedPayloadDigestAlgorithm"],
                "originalRetainedPayloadSha256": audit["originalRetainedPayloadSha256"],
                "sanitizedRetainedPayloadSha256": audit["sanitizedRetainedPayloadSha256"],
                "retainedEventCounts": audit["sanitizedEventCounts"],
                "detectedSecretByteSearchPassed": True,
                "detectedSensitiveProbeCount": audit["detectedSensitiveProbeCount"],
                "redactedAudit": {"path": (output / ("frozen-" + mode) / "redacted-audit.json").relative_to(ROOT).as_posix(),
                                  "sha256": sha(audit_path), "valuesEmitted": False, "valueDigestsEmitted": False},
                "commands": {"path": (output / ("frozen-" + mode) / "commands.json").relative_to(ROOT).as_posix(),
                             "sha256": sha(folder / "commands.json")},
                "originalBytesUnchanged": True, "safeToPackage": True,
            }
            records.append(record)
            print(f"{mode}: disclosure records removed; all retained payloads/counts match; detected-value search passed.",
                  flush=True)
        receipt = {
            "format": 1, "status": "passed", "safeToPackage": True, "createdEpochNs": time.time_ns(),
            "recordings": records,
            "tool": {"jdk": str(jdk), "jfrLauncherSha256": sha(jfr), "javaLauncherSha256": sha(java),
                     "releaseFileSha256": sha(jdk / "release"), "reviewedSourceEntries": source_entries},
            "auditorSource": {"path": auditor.relative_to(ROOT).as_posix(), "sha256": sha(auditor)},
            "runnerSource": {"path": Path(__file__).resolve().relative_to(ROOT).as_posix(),
                             "sha256": sha(Path(__file__).resolve())},
            "originalProfileSummarySha256": sha(summary_path),
            "originalRecordingsIncludedInDelivery": False,
            "proofScope": "Every retained event's complete decoded field tree and start/end timestamps are hashed in order. "
                          "All event counts must match except the four explicitly removed disclosure types. "
                          "Detected sensitive values are searched in delivered bytes without printing values or value hashes. "
                          "This is not a universal detector for arbitrary unidentified secrets.",
            "privateWorkingDirectory": str(work),
        }
        write_new(staging / "disclosure-verification.json", receipt)
        (staging / "README.md").write_text(
            "# Scrubbed JFR delivery recordings\n\n"
            "These separate files omit InitialEnvironmentVariable, InitialSystemProperty, SystemProcess and "
            "InitialSecurityProperty events. The original recordings remain unchanged outside the delivery. "
            "The receipt links both digests, exact executed commands, a redacted name/presence audit, and matching "
            "complete retained-event payload digests/counts. No performance event was deliberately removed or altered.\n\n"
            "Analysis can be regenerated from these delivered recordings. The historical all-event counts differ by "
            "the four removed types; analysis-selected event payloads remain identical. Recreating the scrub itself "
            "requires access to the privately retained originals with the receipt's exact digests. Command files preserve "
            "the original execution paths; use fresh destination paths when reproducing.\n\n"
            "The value detector's explicit scope is recorded in the redacted audits. Passing proves absence of the "
            "detected candidate values in the searched encodings, not universal absence of every conceivable secret.\n",
            encoding="utf-8")
        publish_no_replace(staging, output)
        print(f"Published separate scrubbed delivery recordings: {output}", flush=True)
    except BaseException:
        # Keep failed scratch artifacts private and available for diagnosis; publish nothing.
        print(f"Sanitization blocked; unpublished working artifacts retained in {work}", file=sys.stderr)
        raise


if __name__ == "__main__":
    try:
        main()
    except BaseException as error:
        # Avoid exception messages from parsers or tools that could quote input values.
        print("Sanitization did not publish successfully; exception type: " + type(error).__name__, file=sys.stderr)
        raise SystemExit(1)
